<?php
declare(strict_types=1);
require_once __DIR__ . '/_bootstrap.php';
if (!$isAdmin) { http_response_code(403); exit('Akses ditolak.'); }
require_once __DIR__ . '/../packages/AttendanceReport/AttendanceReport.php';
use App\Reports\AttendanceReport;
$service = new AttendanceReport(db());
[$from, $to] = $service->normalizeRange($_GET['from'] ?? date('Y-m-01'), $_GET['to'] ?? date('Y-m-d'));
$classId = isset($_GET['kelas']) && ctype_digit((string)$_GET['kelas']) ? (int)$_GET['kelas'] : null;
$report = $service->build($from, $to, $classId);
$classes = $service->classes();
$pageKey='reports'; $pageTitle='Laporan Presensi'; $pageSub='Unduh rekap satu bulan atau beberapa bulan dalam Excel per kelas atau PDF';
require __DIR__ . '/../templates/admin-head.php';
$query = fn(string $format): string => '/admin/report-download.php?' . http_build_query(['from'=>$from,'to'=>$to,'kelas'=>$classId,'format'=>$format]);
?>
