 <section class="card"><div class="card__head"><div><h2 class="card__title">Buat laporan</h2><p class="card__sub">Pilih periode sampai maksimal 24 bulan. Excel otomatis membuat satu sheet untuk setiap kelas.</p></div></div><div class="card__body"><form class="report-filter" method="get"><div class="field"><label class="field__label" for="from">Dari tanggal</label><input id="from" name="from" type="date" value="<?= esc($from) ?>" required></div><div class="field"><label class="field__label" for="to">Sampai tanggal</label><input id="to" name="to" type="date" value="<?= esc($to) ?>" required></div><div class="field"><label class="field__label" for="kelas">Kelas</label><select id="kelas" name="kelas"><option value="">Semua kelas</option><?php foreach($classes as $c): ?><option value="<?= (int)$c['id'] ?>" <?= $classId===(int)$c['id']?'selected':'' ?>><?= esc($c['nama_kelas']) ?></option><?php endforeach; ?></select></div><button class="btn btn--primary report-submit" type="submit"><i class="fa-solid fa-filter"></i>Tampilkan</button></form></div></section>
 <section class="grid grid--kpi"><div class="kpi kpi--ok"><span class="kpi__ic"><i class="fa-solid fa-user-check"></i></span><div class="kpi__body"><span class="kpi__value"><?= $report['summary']['hadir'] ?></span><span class="kpi__label">Baris hadir</span></div></div><div class="kpi kpi--info"><span class="kpi__ic"><i class="fa-solid fa-right-from-bracket"></i></span><div class="kpi__body"><span class="kpi__value"><?= $report['summary']['pulang'] ?></span><span class="kpi__label">Scan pulang</span></div></div><div class="kpi kpi--warn"><span class="kpi__ic"><i class="fa-solid fa-clock"></i></span><div class="kpi__body"><span class="kpi__value"><?= $report['summary']['telat'] ?></span><span class="kpi__label">Terlambat</span></div></div><div class="kpi kpi--muted"><span class="kpi__ic"><i class="fa-solid fa-file-signature"></i></span><div class="kpi__body"><span class="kpi__value"><?= $report['summary']['izin'] ?></span><span class="kpi__label">Izin & sakit</span></div></div></section>
 <section class="card"><div class="card__head"><div><h2 class="card__title">Unduh laporan</h2><p class="card__sub"><?= esc($from) ?> sampai <?= esc($to) ?></p></div></div><div class="card__body"><div class="report-actions"><a class="report-download-card report-download-card--excel" href="<?= esc($query('xlsx')) ?>"><span class="report-download-card__icon"><i class="fa-solid fa-file-excel"></i></span><span><span class="report-download-card__title">Excel laporan (.xlsx)</span><span class="report-download-card__sub">Excel native, satu sheet per kelas + izin/sakit</span></span><i class="fa-solid fa-arrow-down report-download-card__go"></i></a><a class="report-download-card report-download-card--pdf" href="<?= esc($query('pdf')) ?>"><span class="report-download-card__icon"><i class="fa-solid fa-file-pdf"></i></span><span><span class="report-download-card__title">PDF laporan</span><span class="report-download-card__sub">Siap cetak dan arsip</span></span><i class="fa-solid fa-arrow-down report-download-card__go"></i></a></div><p class="field__hint" style="margin-top:10px">Laporan berisi presensi harian dan sheet izin/sakit. Data hanya dibaca, tidak mengubah database.</p></div></section>
 <section class="card"><div class="card__head"><div><h2 class="card__title">Preview absensi</h2><p class="card__sub">Menampilkan maksimal 100 baris pertama.</p></div></div><div class="report-preview"><table class="table"><thead><tr><th>Tanggal</th><th>Nama</th><th>Kelas</th><th>Masuk</th><th>Pulang</th><th>Status</th></tr></thead><tbody><?php foreach(array_slice($report['rows'],0,100) as $r): ?><tr><td><?= esc($r['tanggal']) ?></td><td><?= esc($r['nama_lengkap']) ?></td><td><?= esc($r['nama_kelas']?:'-') ?></td><td><?= esc($r['waktu_masuk']?:'-') ?></td><td><?= esc($r['waktu_pulang']?:'-') ?></td><td><?= esc($r['status_masuk']?:'hadir') ?></td></tr><?php endforeach; ?><?php if(!$report['rows']): ?><tr><td colspan="6">Tidak ada data untuk periode ini.</td></tr><?php endif; ?></tbody></table></div></section>
